-- Reviewed senior batch 012; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":3731,"word":"organism","meaning":"有機體","example":"A single-celled organism appeared under the classroom microscope.","example_zh":"教室顯微鏡下出現一個單細胞生物。","original_meaning":"有機體","original_example":"Every organism needs water to survive.","original_example_zh":"每個生物都需要水才能生存。"},{"source_id":3732,"word":"orient","meaning":"確定方向；定位","example":"We used a compass to orient the map before starting the hike.","example_zh":"健行出發前，我們用指南針確定地圖方向。","original_meaning":"定位","original_example":"Maps help us orient ourselves.","original_example_zh":"地圖幫助我們辨別方位。"},{"source_id":3733,"word":"orthodox","meaning":"正統的","example":"The carpenter preferred an orthodox method of joining the wooden beams.","example_zh":"木匠偏好以傳統正統的方法接合木梁。","original_meaning":"正統的","original_example":"They follow orthodox traditions.","original_example_zh":"他們遵循正統傳統。"},{"source_id":3734,"word":"outbreak","meaning":"爆發","example":"An outbreak of mold damaged several plants in the greenhouse.","example_zh":"溫室裡黴菌爆發，損害了幾株植物。","original_meaning":"爆發","original_example":"There was an outbreak of disease.","original_example_zh":"爆發了疫情。"},{"source_id":3735,"word":"outrage","meaning":"憤怒","example":"The illegal dumping caused outrage among the riverside residents.","example_zh":"非法傾倒垃圾讓河岸居民憤怒。","original_meaning":"憤怒","original_example":"The news caused public outrage.","original_example_zh":"這則新聞引起公眾憤慨。"},{"source_id":3736,"word":"outsource","meaning":"外包","example":"The school will outsource the repair of its old piano to a specialist.","example_zh":"學校將把舊鋼琴維修工作外包給專家。","original_meaning":"外包","original_example":"The company decided to outsource the work.","original_example_zh":"公司決定將工作外包。"},{"source_id":3737,"word":"overhaul","meaning":"全面檢修","example":"The mechanic will overhaul the old engine before the bus returns to service.","example_zh":"技師將全面檢修舊引擎，公車才恢復行駛。","original_meaning":"全面檢修","original_example":"The car needs a complete overhaul.","original_example_zh":"這輛車需要徹底大修。"},{"source_id":3738,"word":"oversight","meaning":"監督","example":"The students built the bridge model under the teacher's oversight.","example_zh":"學生在老師監督下建造模型橋。","original_meaning":"監督","original_example":"Government oversight is necessary.","original_example_zh":"政府監管是必要的。"},{"source_id":3739,"word":"overthrow","meaning":"推翻","example":"The history model showed how citizens sought to overthrow an unjust ruler.","example_zh":"歷史模型呈現人民如何設法推翻不公正的統治者。","original_meaning":"推翻","original_example":"The rebels tried to overthrow the government.","original_example_zh":"叛軍試圖推翻政府。"},{"source_id":3740,"word":"oxide","meaning":"氧化物","example":"The lesson identified rust as a mixture containing iron oxide.","example_zh":"課程指出，鐵鏽是含有氧化鐵的混合物。","original_meaning":"氧化物","original_example":"Iron oxide forms rust.","original_example_zh":"氧化鐵會生鏽。"},{"source_id":3741,"word":"oxygen","meaning":"氧氣","example":"The science model showed two oxygen atoms joined in a molecule of oxygen gas.","example_zh":"科學模型顯示，氧氣分子由兩個氧原子結合而成。","original_meaning":"氧氣","original_example":"Oxygen is vital for breathing.","original_example_zh":"氧氣對呼吸至關重要。"},{"source_id":3742,"word":"ozone","meaning":"臭氧","example":"The students built an ozone model using three oxygen atoms.","example_zh":"學生用三個氧原子製作臭氧模型。","original_meaning":"臭氧","original_example":"The ozone layer protects Earth.","original_example_zh":"臭氧層保護著地球。"},{"source_id":3743,"word":"pacifism","meaning":"和平主義","example":"His belief in pacifism led him to organize a peaceful discussion.","example_zh":"他對和平主義的信念促使他籌辦和平對話。","original_meaning":"和平主義","original_example":"He believes in pacifism.","original_example_zh":"他信奉和平主義。"},{"source_id":3744,"word":"pandemic","meaning":"大流行","example":"The museum documented how a pandemic affected communities across the world.","example_zh":"博物館記錄大流行如何影響世界各地的社區。","original_meaning":"大流行","original_example":"The pandemic affected the whole world.","original_example_zh":"這場大流行病影響了全世界。"},{"source_id":3745,"word":"paradigm","meaning":"典範；思考模式","example":"The new teaching paradigm placed students' questions at the center of each lesson.","example_zh":"新的教學典範把學生的問題放在每堂課的核心。","original_meaning":"典範","original_example":"This theory became a new paradigm.","original_example_zh":"這項理論成為了新的典範。"},{"source_id":3746,"word":"paragraph","meaning":"段落","example":"She revised the opening paragraph of her story.","example_zh":"她修改故事的第一段。","original_meaning":"段落","original_example":"Each paragraph explains one idea.","original_example_zh":"每個段落闡述一個概念。"},{"source_id":3747,"word":"parameter","meaning":"參數","example":"We changed one parameter to see how it affected the model robot's speed.","example_zh":"我們改變一個參數，觀察它如何影響模型機器人的速度。","original_meaning":"參數","original_example":"Adjust the parameter to improve performance.","original_example_zh":"調整參數以提升效能。"},{"source_id":3748,"word":"parasite","meaning":"寄生蟲","example":"The museum displayed an enlarged model of a parasite that lives on fish.","example_zh":"博物館展示一種寄生在魚身上的寄生蟲放大模型。","original_meaning":"寄生蟲","original_example":"The parasite lives inside its host.","original_example_zh":"寄生蟲寄生於宿主體內。"},{"source_id":3749,"word":"parliament","meaning":"議會","example":"The visitors watched parliament debate a proposal for a new library.","example_zh":"訪客觀看議會辯論興建新圖書館的提案。","original_meaning":"議會","original_example":"The parliament passed a new law.","original_example_zh":"國會通過了一項新法律。"},{"source_id":3750,"word":"participation","meaning":"參與","example":"Everyone's participation helped make the school garden a success.","example_zh":"每個人的參與使校園花園順利完成。","original_meaning":"參與","original_example":"Student participation is encouraged.","original_example_zh":"鼓勵學生參與。"},{"source_id":3751,"word":"partition","meaning":"隔板；分隔","example":"A movable partition divided the large classroom into two study areas.","example_zh":"可移動隔板把大教室分成兩個學習區。","original_meaning":"分割","original_example":"The country faced partition.","original_example_zh":"該國面臨分裂。"},{"source_id":3752,"word":"partnership","meaning":"合作關係；合夥","example":"The partnership between the school and the museum created new learning opportunities.","example_zh":"學校與博物館的合作帶來新的學習機會。","original_meaning":"合夥","original_example":"They formed a business partnership.","original_example_zh":"他們建立了商業夥伴關係。"},{"source_id":3753,"word":"passport","meaning":"護照","example":"She checked that her passport was safely inside her travel bag.","example_zh":"她確認護照已安全放在旅行袋裡。","original_meaning":"護照","original_example":"You need a passport to travel abroad.","original_example_zh":"出國旅行需要護照。"},{"source_id":3754,"word":"patent","meaning":"專利","example":"The inventor received a patent for her new water-saving device.","example_zh":"發明家為新型節水裝置取得專利。","original_meaning":"專利","original_example":"The company filed for a patent.","original_example_zh":"該公司申請了專利。"},{"source_id":3755,"word":"pathogen","meaning":"病原體","example":"The biology exhibit showed a magnified model of a pathogen.","example_zh":"生物展覽展示病原體的放大模型。","original_meaning":"病原體","original_example":"The pathogen spreads quickly.","original_example_zh":"病原體傳播迅速。"},{"source_id":3756,"word":"patriotism","meaning":"愛國心","example":"Their patriotism inspired them to help restore the country's historic buildings.","example_zh":"愛國心鼓舞他們協助修復國家的歷史建築。","original_meaning":"愛國心","original_example":"Patriotism inspired the soldiers.","original_example_zh":"愛國主義激勵了士兵。"},{"source_id":3757,"word":"patronage","meaning":"贊助","example":"The painter continued her work with the patronage of a local foundation.","example_zh":"畫家獲得當地基金會贊助，得以持續創作。","original_meaning":"贊助","original_example":"The artist received patronage.","original_example_zh":"這位藝術家獲得了贊助。"},{"source_id":3758,"word":"peacekeeping","meaning":"維和","example":"The exhibit described peacekeeping efforts that helped communities rebuild.","example_zh":"展覽介紹協助社區重建的維和行動。","original_meaning":"維和","original_example":"Peacekeeping forces were deployed.","original_example_zh":"維和部隊被部署。"},{"source_id":3759,"word":"peasant","meaning":"農民","example":"The historical painting showed a peasant tending a small field.","example_zh":"歷史畫作呈現一位農民照料小田地。","original_meaning":"農民","original_example":"The peasant worked in the fields.","original_example_zh":"農民在田裡勞作。"},{"source_id":3760,"word":"pedagogy","meaning":"教學法","example":"The workshop explored a pedagogy based on hands-on experiments.","example_zh":"工作坊探討以實作實驗為基礎的教學法。","original_meaning":"教學法","original_example":"Modern pedagogy improves teaching methods.","original_example_zh":"現代教育學改善了教學方法。"},{"source_id":3761,"word":"pedestrian","meaning":"行人","example":"The pedestrian waited until the crossing was safe.","example_zh":"那位行人等到可以安全通行才過馬路。","original_meaning":"行人","original_example":"The driver waited until every pedestrian had crossed the street.","original_example_zh":"司機等到所有行人都過完馬路才前進。"},{"source_id":3762,"word":"penicillin","meaning":"盤尼西林","example":"The science exhibit explained the discovery of penicillin.","example_zh":"科學展覽介紹盤尼西林的發現。","original_meaning":"盤尼西林","original_example":"Penicillin saved many lives.","original_example_zh":"青黴素拯救了許多生命。"},{"source_id":3763,"word":"peninsula","meaning":"半島","example":"The map showed a peninsula surrounded by water on three sides.","example_zh":"地圖顯示一個三面環水的半島。","original_meaning":"半島","original_example":"The peninsula extends into the sea.","original_example_zh":"半島延伸入海。"},{"source_id":3764,"word":"pension","meaning":"退休金","example":"Her pension helped cover daily expenses after she retired.","example_zh":"退休後，她用退休金支付日常開銷。","original_meaning":"退休金","original_example":"He relies on his pension after retirement.","original_example_zh":"他退休後依靠退休金生活。"},{"source_id":3765,"word":"perception","meaning":"感知","example":"The optical illusion challenged our perception of the two shapes.","example_zh":"視覺錯覺挑戰我們對兩個形狀的感知。","original_meaning":"感知","original_example":"Perception differs from person to person.","original_example_zh":"每個人的看法各不相同。"},{"source_id":3766,"word":"peril","meaning":"危險","example":"The guide kept the hikers away from the peril of the unstable cliff edge.","example_zh":"嚮導讓健行者遠離不穩定崖邊的危險。","original_meaning":"危險","original_example":"The climbers faced great peril.","original_example_zh":"登山者面臨極大危險。"},{"source_id":3767,"word":"periodical","meaning":"期刊","example":"She found a useful article in a science periodical.","example_zh":"她在一本科學期刊裡找到有用文章。","original_meaning":"期刊","original_example":"She reads scientific periodicals.","original_example_zh":"她閱讀科學期刊。"},{"source_id":3768,"word":"persecution","meaning":"迫害","example":"The memorial honored people who had suffered religious persecution.","example_zh":"紀念館向遭受宗教迫害的人們致敬。","original_meaning":"迫害","original_example":"They suffered religious persecution.","original_example_zh":"他們遭受宗教迫害。"},{"source_id":3769,"word":"personnel","meaning":"人員","example":"The library personnel helped visitors locate the exhibition room.","example_zh":"圖書館人員協助訪客找到展覽室。","original_meaning":"人員","original_example":"The company hired new personnel.","original_example_zh":"該公司聘用了新員工。"},{"source_id":3770,"word":"pesticide","meaning":"殺蟲劑","example":"The farmer kept the pesticide in a locked storage cabinet.","example_zh":"農民把殺蟲劑放在上鎖的儲物櫃。","original_meaning":"殺蟲劑","original_example":"Farmers use pesticide to protect crops.","original_example_zh":"農民使用農藥來保護作物。"},{"source_id":3771,"word":"petroleum","meaning":"石油","example":"The museum used a model to explain how petroleum is found underground.","example_zh":"博物館用模型解說地下石油的分布。","original_meaning":"石油","original_example":"Petroleum is a major energy source.","original_example_zh":"石油是主要的能源。"},{"source_id":3772,"word":"pharmaceutical","meaning":"製藥的","example":"The pharmaceutical laboratory tested the quality of its products.","example_zh":"製藥實驗室檢驗產品品質。","original_meaning":"製藥的","original_example":"He works in the pharmaceutical industry.","original_example_zh":"他在製藥業工作。"},{"source_id":3773,"word":"philanthropy","meaning":"慈善","example":"Her philanthropy helped provide books for rural schools.","example_zh":"她的慈善捐助幫助偏鄉學校取得書籍。","original_meaning":"慈善","original_example":"He is known for his philanthropy.","original_example_zh":"他以慈善事業聞名。"},{"source_id":3774,"word":"photosynthesis","meaning":"光合作用","example":"The lesson explained how light supports photosynthesis in green plants.","example_zh":"課程說明光如何支持綠色植物的光合作用。","original_meaning":"光合作用","original_example":"Plants use photosynthesis to make food.","original_example_zh":"植物透過光合作用製造養分。"},{"source_id":3775,"word":"physicist","meaning":"物理學家","example":"The physicist demonstrated how a pendulum swings.","example_zh":"物理學家示範鐘擺如何擺動。","original_meaning":"物理學家","original_example":"The physicist explained the theory.","original_example_zh":"那位物理學家解釋了該理論。"},{"source_id":3776,"word":"physiology","meaning":"生理學","example":"The physiology lesson explored how muscles move the arm.","example_zh":"生理學課程探討肌肉如何使手臂活動。","original_meaning":"生理學","original_example":"Physiology studies body functions.","original_example_zh":"生理學研究身體機能。"},{"source_id":3777,"word":"pilgrimage","meaning":"朝聖","example":"The travelers made a pilgrimage to a sacred mountain shrine.","example_zh":"旅人前往神聖的山間聖地朝聖。","original_meaning":"朝聖","original_example":"They went on a pilgrimage.","original_example_zh":"他們去朝聖。"},{"source_id":3778,"word":"pinnacle","meaning":"頂峰","example":"The climbers admired the rocky pinnacle from a safe viewpoint.","example_zh":"登山者從安全觀景點欣賞岩石尖峰。","original_meaning":"頂峰","original_example":"She reached the pinnacle of her career.","original_example_zh":"她達到了事業的巔峰。"},{"source_id":3779,"word":"plaintiff","meaning":"原告","example":"The plaintiff presented documents to support her claim.","example_zh":"原告提出文件支持她的主張。","original_meaning":"原告","original_example":"The plaintiff filed a lawsuit.","original_example_zh":"原告提起訴訟。"},{"source_id":3780,"word":"plantation","meaning":"種植園","example":"The students visited a tea plantation on the hillside.","example_zh":"學生參觀山坡上的茶葉種植園。","original_meaning":"種植園","original_example":"The plantation grows sugarcane.","original_example_zh":"這座種植園種植甘蔗。"},{"source_id":3781,"word":"platform","meaning":"平台","example":"The speaker stepped onto the platform before addressing the audience.","example_zh":"講者走上講臺，再向聽眾發言。","original_meaning":"平台","original_example":"This platform supports many users.","original_example_zh":"這個平台支援眾多使用者。"},{"source_id":3782,"word":"plausibility","meaning":"合理性","example":"We tested the plausibility of the bridge design with a small model.","example_zh":"我們用小模型測試橋梁設計是否合理可行。","original_meaning":"合理性","original_example":"The theory lacks plausibility.","original_example_zh":"該理論缺乏合理性。"},{"source_id":3783,"word":"playwright","meaning":"劇作家","example":"The playwright revised the final scene during rehearsal.","example_zh":"劇作家在排演時修改最後一幕。","original_meaning":"劇作家","original_example":"The playwright wrote many famous works.","original_example_zh":"這位劇作家寫了許多著名作品。"},{"source_id":3784,"word":"plead","meaning":"懇求","example":"The students pleaded with the coach for one more practice session.","example_zh":"學生懇求教練再安排一次練習。","original_meaning":"懇求","original_example":"He pleaded for forgiveness.","original_example_zh":"他懇求原諒。"},{"source_id":3785,"word":"plebiscite","meaning":"公民投票","example":"The island held a plebiscite on its political future.","example_zh":"島上就政治未來舉行公民投票。","original_meaning":"公民投票","original_example":"The country held a plebiscite.","original_example_zh":"該國舉行了一次全民公投。"},{"source_id":3786,"word":"plurality","meaning":"相對多數","example":"She won a plurality of the votes, though she received less than half.","example_zh":"她贏得相對多數票，雖然票數未過半。","original_meaning":"多數","original_example":"The candidate won by a plurality.","original_example_zh":"該候選人以相對多數勝選。"},{"source_id":3787,"word":"pneumonia","meaning":"肺炎","example":"The medical exhibit explained how pneumonia can affect the lungs.","example_zh":"醫學展覽解說肺炎如何影響肺部。","original_meaning":"肺炎","original_example":"He was diagnosed with pneumonia.","original_example_zh":"他被診斷出患有肺炎。"},{"source_id":3788,"word":"polarization","meaning":"極化","example":"The debate revealed growing polarization between the two groups.","example_zh":"辯論顯示兩個群體的意見日益兩極化。","original_meaning":"極化","original_example":"Political polarization is increasing.","original_example_zh":"政治兩極化日益加劇。"},{"source_id":3789,"word":"portfolio","meaning":"投資組合","example":"The lesson compared a diversified portfolio with one containing only a single investment.","example_zh":"課程比較分散投資的組合與僅含單一投資的組合。","original_meaning":"投資組合","original_example":"He manages a diverse investment portfolio.","original_example_zh":"他管理著一個多元化的投資組合。"},{"source_id":3790,"word":"posthumous","meaning":"死後的","example":"The museum organized a posthumous exhibition of the artist's paintings.","example_zh":"藝術家逝世後，博物館為她舉辦遺作展。","original_meaning":"死後的","original_example":"The award was given posthumous recognition.","original_example_zh":"該獎項是追授的。"},{"source_id":3791,"word":"postulate","meaning":"假設","example":"The researchers postulate that the two fragments came from the same vase.","example_zh":"研究者假設，兩塊碎片來自同一個花瓶。","original_meaning":"假設","original_example":"Scientists postulate new theories based on evidence.","original_example_zh":"科學家根據證據提出新理論。"},{"source_id":3792,"word":"potency","meaning":"效力；強度","example":"The dark pigment's potency meant that only a tiny amount changed the whole mixture.","example_zh":"深色顏料的著色力很強，一點點就改變整碗混合物的顏色。","original_meaning":"效力","original_example":"The drug has high potency.","original_example_zh":"這種藥效力很強。"},{"source_id":3793,"word":"pragmatism","meaning":"實用主義；務實態度","example":"Her pragmatism led the team to repair the old tables instead of buying new ones.","example_zh":"她的務實態度讓團隊選擇修理舊桌子，而非購買新桌。","original_meaning":"實用主義","original_example":"His pragmatism helped solve the problem.","original_example_zh":"他的務實態度有助於解決問題。"},{"source_id":3794,"word":"preamble","meaning":"序言","example":"We read the preamble before discussing the agreement's main rules.","example_zh":"我們先讀序言，再討論協議的主要規則。","original_meaning":"序言","original_example":"The preamble explains the purpose of the document.","original_example_zh":"前言闡述了該文件的宗旨。"},{"source_id":3795,"word":"precinct","meaning":"選區","example":"The map divided the city into several voting precincts.","example_zh":"地圖把城市分成數個投票選區。","original_meaning":"選區","original_example":"Each precinct reported its voting results.","original_example_zh":"每個選區都報告了投票結果。"},{"source_id":3796,"word":"predecessor","meaning":"前任","example":"The new principal thanked her predecessor for improving the school library.","example_zh":"新校長感謝前任改善學校圖書館。","original_meaning":"前任","original_example":"She followed in her predecessor’s footsteps.","original_example_zh":"她追隨前任的腳步。"},{"source_id":3797,"word":"predictor","meaning":"預測因子","example":"The amount of recent rain was a useful predictor of the stream's water level.","example_zh":"近期降雨量是預測溪流水位的有用指標。","original_meaning":"預測因子","original_example":"This variable is a strong predictor of success.","original_example_zh":"這個變數是成功的強有力預測指標。"},{"source_id":3798,"word":"predominance","meaning":"優勢；占多數","example":"The predominance of pine trees gave the forest a distinctive scent.","example_zh":"森林裡松樹占多數，因此帶有獨特香氣。","original_meaning":"主導","original_example":"The predominance of one group caused imbalance.","original_example_zh":"某個群體的佔主導地位導致了失衡。"},{"source_id":3799,"word":"preemptive","meaning":"先發制人的；預先防範的","example":"The gardeners took preemptive action by supporting the young trees before the storm.","example_zh":"園丁在暴風雨前支撐幼樹，預先防範損害。","original_meaning":"先發制人的","original_example":"The country launched a preemptive strike.","original_example_zh":"該國發動了先發制人的打擊。"},{"source_id":3800,"word":"prerogative","meaning":"特權；專屬職權","example":"Choosing the final design was the project leader's prerogative.","example_zh":"選擇最終設計是專案負責人的職權。","original_meaning":"特權","original_example":"Voting is a citizen’s prerogative.","original_example_zh":"投票是公民的特權。"},{"source_id":3801,"word":"presidency","meaning":"總統任期","example":"The archive displayed photographs from her presidency.","example_zh":"檔案館展出她擔任總統期間的照片。","original_meaning":"總統任期","original_example":"His presidency lasted for four years.","original_example_zh":"他的總統任期為四年。"},{"source_id":3802,"word":"presumably","meaning":"大概","example":"The muddy boots presumably belonged to the gardener working outside.","example_zh":"那雙沾泥靴子大概屬於正在外面工作的園丁。","original_meaning":"大概","original_example":"She is presumably at home now.","original_example_zh":"她現在大概在家裡。"},{"source_id":3803,"word":"prevalence","meaning":"盛行；普遍程度","example":"The survey measured the prevalence of bicycle use among local students.","example_zh":"調查測量當地學生騎自行車的普遍程度。","original_meaning":"盛行","original_example":"The prevalence of the disease increased.","original_example_zh":"該疾病的流行率上升。"},{"source_id":3804,"word":"privatization","meaning":"私有化","example":"The lesson examined the privatization of a state-owned factory.","example_zh":"課程探討國營工廠的私有化。","original_meaning":"私有化","original_example":"Privatization changed the industry.","original_example_zh":"私有化改變了該產業。"},{"source_id":3805,"word":"probation","meaning":"緩刑","example":"The judge placed the offender on probation under supervision.","example_zh":"法官判處違法者接受監督下的緩刑。","original_meaning":"緩刑","original_example":"He was released on probation.","original_example_zh":"他獲准緩刑釋放。"},{"source_id":3806,"word":"procurement","meaning":"採購","example":"The school improved its procurement of books by comparing several suppliers.","example_zh":"學校比較多家供應商，改善書籍採購。","original_meaning":"採購","original_example":"The company handles procurement efficiently.","original_example_zh":"該公司高效地處理採購事宜。"},{"source_id":3807,"word":"prodigy","meaning":"神童","example":"The young chess prodigy solved the difficult puzzle in moments.","example_zh":"年輕西洋棋神童片刻間解開困難棋題。","original_meaning":"神童","original_example":"The child prodigy amazed everyone.","original_example_zh":"這位神童讓所有人驚嘆不已。"},{"source_id":3808,"word":"proficiency","meaning":"熟練","example":"Her proficiency in woodworking showed in the smooth, precise joints.","example_zh":"平滑精準的接合處展現她熟練的木工技術。","original_meaning":"熟練","original_example":"She has high proficiency in English.","original_example_zh":"她的英語能力很強。"},{"source_id":3809,"word":"prognosis","meaning":"預後","example":"The doctor discussed the patient's prognosis with care and honesty.","example_zh":"醫師謹慎而坦誠地說明病人的預後。","original_meaning":"預後","original_example":"The doctor gave a positive prognosis.","original_example_zh":"醫生給出了樂觀的預後。"},{"source_id":3810,"word":"proliferation","meaning":"擴散；大量增生","example":"The warm weather encouraged the proliferation of algae in the pond.","example_zh":"溫暖天氣促使池塘藻類大量增生。","original_meaning":"擴散","original_example":"There is a rapid proliferation of technology.","original_example_zh":"科技正迅速普及。"},{"source_id":3811,"word":"prophecy","meaning":"預言","example":"The old story contained a prophecy about a bridge joining the two villages.","example_zh":"古老故事中有一則預言，說一座橋將連接兩個村莊。","original_meaning":"預言","original_example":"The ancient prophecy came true.","original_example_zh":"古老的預言成真了。"},{"source_id":3812,"word":"proposition","meaning":"提議","example":"Her proposition was to turn the unused courtyard into a reading garden.","example_zh":"她提議把閒置庭院改造成閱讀花園。","original_meaning":"提議","original_example":"He made a bold proposition.","original_example_zh":"他提出了一個大膽的提議。"},{"source_id":3813,"word":"proprietor","meaning":"業主","example":"The bookstore proprietor welcomed the students to the reading event.","example_zh":"書店業主歡迎學生參加閱讀活動。","original_meaning":"業主","original_example":"The proprietor owns the shop.","original_example_zh":"店主擁有這家店。"},{"source_id":3814,"word":"prosecution","meaning":"起訴；起訴方","example":"The prosecution presented evidence during the trial.","example_zh":"起訴方在審判中提出證據。","original_meaning":"起訴","original_example":"The prosecution presented strong evidence.","original_example_zh":"檢方提出了有力的證據。"},{"source_id":3815,"word":"protocol","meaning":"協議","example":"The teams agreed on a protocol for sharing their research data.","example_zh":"各團隊就分享研究資料的協議達成共識。","original_meaning":"協議","original_example":"Follow the network protocol strictly.","original_example_zh":"嚴格遵守網路協定。"},{"source_id":3816,"word":"prototype","meaning":"原型","example":"The students tested a prototype of their rainwater collector.","example_zh":"學生測試雨水收集器的原型。","original_meaning":"原型","original_example":"The engineer built a working prototype.","original_example_zh":"工程師建造了一個可運作的原型。"},{"source_id":3817,"word":"provenance","meaning":"來源","example":"The curator investigated the provenance of the old ceramic bowl.","example_zh":"策展人調查古陶碗的來源。","original_meaning":"來源","original_example":"The artifact’s provenance is unclear.","original_example_zh":"該文物的來源不明。"},{"source_id":3818,"word":"provision","meaning":"條款","example":"One provision in the agreement required the garden to remain open to the public.","example_zh":"協議的一項條款要求花園持續對外開放。","original_meaning":"條款","original_example":"The contract includes several provisions.","original_example_zh":"合約包含數項條款。"},{"source_id":3819,"word":"proxy","meaning":"代理","example":"The absent member appointed a proxy to vote on her behalf.","example_zh":"缺席成員指定代理人代她投票。","original_meaning":"代理","original_example":"He voted by proxy at the meeting.","original_example_zh":"他在會議上以委託投票方式投票。"},{"source_id":3820,"word":"pseudonym","meaning":"筆名","example":"The novelist wrote her adventure stories under a pseudonym.","example_zh":"小說家以筆名創作冒險故事。","original_meaning":"筆名","original_example":"The author used a pseudonym.","original_example_zh":"作者使用了筆名。"},{"source_id":3821,"word":"psyche","meaning":"心理","example":"The novel explored the effects of loneliness on the human psyche.","example_zh":"小說探討孤獨對人類心理的影響。","original_meaning":"心理","original_example":"Stress can affect the human psyche.","original_example_zh":"壓力會影響人的心理。"},{"source_id":3822,"word":"publication","meaning":"出版物","example":"The library added a new publication about local wildlife.","example_zh":"圖書館新增一本介紹當地野生動物的出版物。","original_meaning":"出版物","original_example":"The publication gained popularity.","original_example_zh":"該出版物廣受歡迎。"},{"source_id":3823,"word":"purification","meaning":"淨化","example":"The model demonstrated water purification using layers of filter material.","example_zh":"模型展示利用多層濾材進行水的淨化。","original_meaning":"淨化","original_example":"Water purification is essential.","original_example_zh":"淨水至關重要。"},{"source_id":3824,"word":"quarantine","meaning":"隔離","example":"The newly arrived plants stayed in quarantine before entering the greenhouse.","example_zh":"新到的植物進溫室前先接受隔離。","original_meaning":"隔離","original_example":"The patient was placed in quarantine.","original_example_zh":"該患者被隔離。"},{"source_id":3825,"word":"quota","meaning":"配額","example":"Each group received the same quota of materials for the bridge challenge.","example_zh":"每組獲得相同配額的材料，參加模型橋挑戰。","original_meaning":"配額","original_example":"The company met its sales quota.","original_example_zh":"公司達成了銷售配額。"},{"source_id":3826,"word":"quotation","meaning":"引述","example":"She used a short quotation from the poem to support her interpretation.","example_zh":"她引用詩中的短句，支持自己的詮釋。","original_meaning":"引述","original_example":"He included a quotation in his essay.","original_example_zh":"他在文章中引用了一段話。"},{"source_id":3827,"word":"rampant","meaning":"猖獗的","example":"Rampant weeds covered the neglected garden paths.","example_zh":"雜草肆意蔓生，覆蓋了失修花園的步道。","original_meaning":"猖獗的","original_example":"Crime became rampant in the city.","original_example_zh":"犯罪在城裡猖獗。"},{"source_id":3828,"word":"ratification","meaning":"批准","example":"The treaty required ratification before it could take effect.","example_zh":"條約須經批准才能生效。","original_meaning":"批准","original_example":"The treaty required ratification.","original_example_zh":"該條約須經批准。"},{"source_id":3829,"word":"rationale","meaning":"理由","example":"The designer explained the rationale behind the bridge's curved shape.","example_zh":"設計師解釋橋梁採用弧形的理由。","original_meaning":"理由","original_example":"There is a clear rationale behind the decision.","original_example_zh":"這項決定的背後有明確的理由。"},{"source_id":3830,"word":"realism","meaning":"現實主義；寫實風格","example":"The painting's realism made the ordinary kitchen feel familiar.","example_zh":"畫作的寫實風格讓平凡廚房顯得熟悉親切。","original_meaning":"現實主義","original_example":"The painting reflects realism.","original_example_zh":"這幅畫體現了寫實主義。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-organism-01-v1","level":"senior","word":"organism","sort_order":1,"sense":"有機體","alt_zh":"老師陪高中生透過顯微鏡觀察單細胞生物，旁邊有簡單放大模型。","example":"A single-celled organism appeared under the classroom microscope.","example_zh":"教室顯微鏡下出現一個單細胞生物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/organism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-orient-01-v1","level":"senior","word":"orient","sort_order":1,"sense":"確定方向；定位","alt_zh":"高中健行隊在安全步道入口用指南針對準無字地圖。","example":"We used a compass to orient the map before starting the hike.","example_zh":"健行出發前，我們用指南針確定地圖方向。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/orient-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-orthodox-01-v1","level":"senior","word":"orthodox","sort_order":1,"sense":"正統的","alt_zh":"成年木匠在工坊向高中生展示傳統榫接木梁。","example":"The carpenter preferred an orthodox method of joining the wooden beams.","example_zh":"木匠偏好以傳統正統的方法接合木梁。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/orthodox-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-outbreak-01-v1","level":"senior","word":"outbreak","sort_order":1,"sense":"爆發","alt_zh":"園藝老師與高中生檢查溫室內幾盆葉面有黴斑的植物。","example":"An outbreak of mold damaged several plants in the greenhouse.","example_zh":"溫室裡黴菌爆發，損害了幾株植物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/outbreak-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-outrage-01-v1","level":"senior","word":"outrage","sort_order":1,"sense":"憤怒","alt_zh":"居民與高中志工看到河岸堆積垃圾，露出氣憤與失望神情。","example":"The illegal dumping caused outrage among the riverside residents.","example_zh":"非法傾倒垃圾讓河岸居民憤怒。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/outrage-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-outsource-01-v1","level":"senior","word":"outsource","sort_order":1,"sense":"外包","alt_zh":"成年專業調音維修師在學校音樂教室檢修舊鋼琴，老師在旁。","example":"The school will outsource the repair of its old piano to a specialist.","example_zh":"學校將把舊鋼琴維修工作外包給專家。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/outsource-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-overhaul-01-v1","level":"senior","word":"overhaul","sort_order":1,"sense":"全面檢修","alt_zh":"成年技師在安全維修工坊全面檢查放在工作架的公車引擎。","example":"The mechanic will overhaul the old engine before the bus returns to service.","example_zh":"技師將全面檢修舊引擎，公車才恢復行駛。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/overhaul-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-oversight-01-v1","level":"senior","word":"oversight","sort_order":1,"sense":"監督","alt_zh":"老師在工坊近旁指導高中生組裝木製模型橋。","example":"The students built the bridge model under the teacher's oversight.","example_zh":"學生在老師監督下建造模型橋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/oversight-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-overthrow-01-v1","level":"senior","word":"overthrow","sort_order":1,"sense":"推翻","alt_zh":"博物館虛構歷史模型中，成年市民和平集會要求王座上的統治者下台，無武器或文字。","example":"The history model showed how citizens sought to overthrow an unjust ruler.","example_zh":"歷史模型呈現人民如何設法推翻不公正的統治者。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/overthrow-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-oxide-01-v1","level":"senior","word":"oxide","sort_order":1,"sense":"氧化物","alt_zh":"老師向高中生展示生鏽鐵釘與紅褐色氧化鐵樣本，樣本置於封閉透明盒。","example":"The lesson identified rust as a mixture containing iron oxide.","example_zh":"課程指出，鐵鏽是含有氧化鐵的混合物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/oxide-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-oxygen-01-v1","level":"senior","word":"oxygen","sort_order":1,"sense":"氧氣","alt_zh":"老師向高中生展示僅由兩個相同紅色球接合成的氧氣分子教具。","example":"The science model showed two oxygen atoms joined in a molecule of oxygen gas.","example_zh":"科學模型顯示，氧氣分子由兩個氧原子結合而成。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/oxygen-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ozone-01-v1","level":"senior","word":"ozone","sort_order":1,"sense":"臭氧","alt_zh":"高中生在課桌上用三個相同紅球接成彎曲的臭氧分子模型，無其他分子。","example":"The students built an ozone model using three oxygen atoms.","example_zh":"學生用三個氧原子製作臭氧模型。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ozone-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-pacifism-01-v1","level":"senior","word":"pacifism","sort_order":1,"sense":"和平主義","alt_zh":"成年社區成員在圓桌平靜聆聽不同意見，主持人以友善手勢協調。","example":"His belief in pacifism led him to organize a peaceful discussion.","example_zh":"他對和平主義的信念促使他籌辦和平對話。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/pacifism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-pandemic-01-v1","level":"senior","word":"pandemic","sort_order":1,"sense":"大流行","alt_zh":"高中生在公共衛生博物館觀看世界地球模型與不同地區戴口罩人群的歷史照片，無病況。